import inspect
import sys
from enum import Enum, IntEnum, auto


class AutoName(Enum):
    def _generate_next_value_(name, start, count, last_values):
        return name


class RunnerStates(IntEnum):
    READY, STARTING, STARTED, STOPPING, STOPPED, COMPRESSING, PROCESSING = range(7)


class StatusCode(IntEnum):
    OK, ForbiddenStateTransition, ServerError, NoConnection = range(4)


class RAT(str, AutoName):
    LTE = auto()
    NR = auto()


class EPCLogLevel(Enum):
    """Simple Enum for Iphy log level"""

    DEBUG, INFORMATION, CTRL_STAT_INFO, WARNING, ERROR, FATAL, OFF, NO_CHANGE = range(8)


# Fancy way to autodetect all enums created in a module and put them in dictionary for (de)serialize.
PUBLIC_ENUMS: dict[str, Enum] = dict(
    inspect.getmembers(
        sys.modules[__name__],
        lambda member: inspect.isclass(member)
        and member.__module__ == __name__
        and member.__name__ not in ("AutoName",)
        and issubclass(member, Enum),
    )
)
